head.b:skin:
  /*
  -----------------------------------------------
  Theme Name    : GoSmart Tools - Blogger SaaS Edition
  Designed for : Blogger / Blogspot
  Inspired by  : GoSmart Tools SaaS (/)
  Author       : GoSmart Teknologi Creative
  License      : https://gosmartlicense.vercel.app/
  Version      : 2.0.2 (Responsive, Dark Mode, SEO Ready, Clean XML Valid)
  -----------------------------------------------
  */

  :root {
    --gs-primary: #2563eb;
    --gs-primary-hover: #1d4ed8;
    --gs-primary-light: #eff6ff;
    --gs-accent: #06b6d4;
    --gs-gradient: linear-gradient(135deg, #2563eb 0%, #4f46e5 50%, #06b6d4 100%);
    --gs-bg: #f8fafc;
    --gs-card-bg: #ffffff;
    --gs-card-border: #e2e8f0;
    --gs-text: #0f172a;
    --gs-text-muted: #64748b;
    --gs-text-subtle: #94a3b8;
    --gs-header-bg: rgba(255, 255, 255, 0.85);
    --gs-header-border: #e2e8f0;
    --gs-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
    --gs-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
    --gs-radius: 16px;
    --gs-radius-sm: 10px;
    --gs-radius-full: 9999px;
  }

  [data-theme='dark'] {
    --gs-bg: #020617;
    --gs-card-bg: #0f172a;
    --gs-card-border: #1e293b;
    --gs-text: #f8fafc;
    --gs-text-muted: #94a3b8;
    --gs-text-subtle: #64748b;
    --gs-header-bg: rgba(15, 23, 42, 0.85);
    --gs-header-border: #1e293b;
    --gs-primary-light: #1e293b;
    --gs-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
    --gs-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6);
  }

  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  body {
    background-color: var(--gs-bg);
    color: var(--gs-text);
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 15px;
    line-height: 1.6;
    transition: background-color 0.25s ease, color 0.25s ease;
    overflow-x: hidden;
  }

  a {
    color: var(--gs-primary);
    text-decoration: none;
    transition: all 0.2s ease;
  }
  a:hover {
    color: var(--gs-primary-hover);
  }

  img {
    max-width: 100%;
    height: auto;
    display: block;
    border-radius: var(--gs-radius-sm);
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
  }

  .gs-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background: var(--gs-header-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--gs-header-border);
    transition: all 0.2s ease;
  }

  .gs-header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 70px;
  }

  .gs-brand {
    display: flex;
    align-items: center;
    gap: 12px;
    font-weight: 800;
    font-size: 18px;
    color: var(--gs-text);
  }
  .gs-brand-icon {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    background: var(--gs-gradient);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    box-shadow: 0 4px 10px rgba(37, 99, 235, 0.3);
  }
  .gs-brand-icon svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2.2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .gs-nav {
    display: flex;
    align-items: center;
    gap: 24px;
    list-style: none;
  }
  .gs-nav a {
    font-weight: 600;
    font-size: 14px;
    color: var(--gs-text-muted);
  }
  .gs-nav a:hover, .gs-nav a.active {
    color: var(--gs-primary);
  }

  .gs-actions {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .gs-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    font-size: 13px;
    font-weight: 700;
    border-radius: var(--gs-radius-sm);
    border: none;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .gs-btn-primary {
    background: var(--gs-primary);
    color: #ffffff !important;
    box-shadow: 0 2px 6px rgba(37, 99, 235, 0.25);
  }
  .gs-btn-primary:hover {
    background: var(--gs-primary-hover);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
  }
  .gs-btn-ghost {
    background: transparent;
    color: var(--gs-text);
    border: 1px solid var(--gs-card-border);
  }
  .gs-btn-ghost:hover {
    background: var(--gs-card-border);
  }

  .theme-toggle {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    border: 1px solid var(--gs-card-border);
    background: var(--gs-card-bg);
    color: var(--gs-text);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .mobile-toggle {
    display: none;
    width: 38px;
    height: 38px;
    border-radius: 10px;
    border: 1px solid var(--gs-card-border);
    background: var(--gs-card-bg);
    color: var(--gs-text);
    cursor: pointer;
    align-items: center;
    justify-content: center;
  }

  .gs-hero {
    padding: 50px 0 30px;
    text-align: center;
    position: relative;
  }
  .gs-hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--gs-primary-light);
    color: var(--gs-primary);
    border: 1px solid rgba(37, 99, 235, 0.2);
    padding: 6px 14px;
    border-radius: var(--gs-radius-full);
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 16px;
  }
  .gs-hero-title {
    font-size: 36px;
    font-weight: 800;
    line-height: 1.25;
    letter-spacing: -0.02em;
    margin-bottom: 12px;
    color: var(--gs-text);
  }
  .gs-hero-title span {
    background: var(--gs-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .gs-hero-desc {
    max-width: 680px;
    margin: 0 auto 24px;
    font-size: 15px;
    color: var(--gs-text-muted);
  }

  .gs-search-bar {
    max-width: 580px;
    margin: 0 auto;
    position: relative;
  }
  .gs-search-input {
    width: 100%;
    padding: 14px 20px 14px 48px;
    border-radius: var(--gs-radius);
    border: 2px solid var(--gs-card-border);
    background: var(--gs-card-bg);
    color: var(--gs-text);
    font-size: 14px;
    font-family: inherit;
    outline: none;
    box-shadow: var(--gs-shadow);
    transition: all 0.2s ease;
  }
  .gs-search-input:focus {
    border-color: var(--gs-primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
  }
  .gs-search-icon {
    position: absolute;
    left: 16px;
    top: 50%;
    transform: translateY(-50%);
    width: 18px;
    height: 18px;
    color: var(--gs-text-subtle);
  }

  .gs-quick-tools {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
    margin-top: 18px;
  }
  .gs-tool-pill {
    padding: 6px 12px;
    border-radius: 8px;
    background: var(--gs-card-bg);
    border: 1px solid var(--gs-card-border);
    font-size: 12px;
    font-weight: 600;
    color: var(--gs-text-muted);
    transition: all 0.2s ease;
  }
  .gs-tool-pill:hover {
    color: var(--gs-primary);
    border-color: var(--gs-primary);
    transform: translateY(-1px);
  }

  .gs-main-layout {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 32px;
    padding: 30px 0 60px;
  }

  .gs-posts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 24px;
  }

  .gs-post-card {
    background: var(--gs-card-bg);
    border: 1px solid var(--gs-card-border);
    border-radius: var(--gs-radius);
    overflow: hidden;
    box-shadow: var(--gs-shadow);
    transition: all 0.25s ease;
    display: flex;
    flex-direction: column;
  }
  .gs-post-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--gs-shadow-lg);
    border-color: rgba(37, 99, 235, 0.3);
  }

  .gs-post-thumb-wrap {
    position: relative;
    aspect-ratio: 16/9;
    overflow: hidden;
    background: var(--gs-card-border);
  }
  .gs-post-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.35s ease;
  }
  .gs-post-card:hover .gs-post-thumb {
    transform: scale(1.04);
  }

  .gs-post-category {
    position: absolute;
    top: 12px;
    left: 12px;
    background: rgba(37, 99, 235, 0.9);
    backdrop-filter: blur(6px);
    color: #fff;
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .gs-post-body {
    padding: 20px;
    display: flex;
    flex-direction: column;
    flex: 1;
  }

  .gs-post-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 12px;
    color: var(--gs-text-subtle);
    margin-bottom: 8px;
  }

  .gs-post-title {
    font-size: 18px;
    font-weight: 700;
    line-height: 1.4;
    margin-bottom: 10px;
  }
  .gs-post-title a {
    color: var(--gs-text);
  }
  .gs-post-title a:hover {
    color: var(--gs-primary);
  }

  .gs-post-snippet {
    font-size: 13.5px;
    color: var(--gs-text-muted);
    line-height: 1.6;
    margin-bottom: 16px;
    flex: 1;
  }

  .gs-post-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 14px;
    border-top: 1px solid var(--gs-card-border);
    font-size: 13px;
    font-weight: 600;
  }
  .gs-read-more {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: var(--gs-primary);
  }
  .gs-read-more:hover {
    gap: 8px;
  }

  .gs-single-post {
    background: var(--gs-card-bg);
    border: 1px solid var(--gs-card-border);
    border-radius: var(--gs-radius);
    padding: 32px;
    box-shadow: var(--gs-shadow);
  }

  .gs-single-header {
    margin-bottom: 24px;
  }
  .gs-single-title {
    font-size: 30px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: -0.01em;
    color: var(--gs-text);
    margin: 12px 0;
  }

  .gs-single-content {
    font-size: 16px;
    line-height: 1.8;
    color: var(--gs-text);
  }
  .gs-single-content h2 {
    font-size: 22px;
    font-weight: 700;
    margin: 32px 0 16px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--gs-card-border);
    color: var(--gs-text);
  }
  .gs-single-content h3 {
    font-size: 18px;
    font-weight: 700;
    margin: 24px 0 12px;
    color: var(--gs-text);
  }
  .gs-single-content p {
    margin-bottom: 18px;
  }
  .gs-single-content pre, .gs-single-content code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13.5px;
  }
  .gs-single-content code {
    background: var(--gs-primary-light);
    color: var(--gs-primary);
    padding: 2px 6px;
    border-radius: 4px;
  }
  .gs-single-content pre {
    background: #0f172a;
    color: #38bdf8;
    padding: 16px;
    border-radius: var(--gs-radius-sm);
    overflow-x: auto;
    margin: 20px 0;
  }

  .gs-sidebar {
    display: flex;
    flex-direction: column;
    gap: 24px;
  }
  .gs-widget {
    background: var(--gs-card-bg);
    border: 1px solid var(--gs-card-border);
    border-radius: var(--gs-radius);
    padding: 24px;
    box-shadow: var(--gs-shadow);
  }
  .gs-widget-title {
    font-size: 16px;
    font-weight: 700;
    color: var(--gs-text);
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
    position: relative;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--gs-card-border);
  }
  .gs-widget-title::after {
    content: '';
    position: absolute;
    bottom: -1px;
    left: 0;
    width: 36px;
    height: 2px;
    background: var(--gs-primary);
    border-radius: 2px;
  }

  .gs-saas-banner-widget {
    background: linear-gradient(135deg, #1e3a8a 0%, #2563eb 100%);
    border-radius: var(--gs-radius);
    padding: 24px;
    color: #fff;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .gs-saas-banner-widget h4 {
    font-size: 18px;
    font-weight: 800;
    margin-bottom: 8px;
  }
  .gs-saas-banner-widget p {
    font-size: 13px;
    opacity: 0.9;
    margin-bottom: 16px;
    line-height: 1.5;
  }

  .gs-footer {
    background: var(--gs-card-bg);
    border-top: 1px solid var(--gs-card-border);
    padding: 48px 0 24px;
    margin-top: 40px;
  }
  .gs-footer-inner {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 40px;
    margin-bottom: 36px;
  }
  .gs-footer-desc {
    font-size: 13.5px;
    color: var(--gs-text-muted);
    margin-top: 12px;
    max-width: 340px;
  }
  .gs-footer-col h5 {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 16px;
    color: var(--gs-text);
  }
  .gs-footer-col ul {
    list-style: none;
  }
  .gs-footer-col ul li {
    margin-bottom: 8px;
  }
  .gs-footer-col ul a {
    font-size: 13.5px;
    color: var(--gs-text-muted);
  }
  .gs-footer-col ul a:hover {
    color: var(--gs-primary);
  }

  .gs-footer-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 24px;
    border-top: 1px solid var(--gs-card-border);
    font-size: 13px;
    color: var(--gs-text-muted);
  }

  @media (max-width: 991px) {
    .gs-main-layout {
      grid-template-columns: 1fr;
    }
    .gs-footer-inner {
      grid-template-columns: 1fr 1fr;
    }
  }

  @media (max-width: 768px) {
    .gs-nav {
      display: none;
    }
    .mobile-toggle {
      display: flex;
    }
    .gs-hero-title {
      font-size: 28px;
    }
    .gs-footer-inner {
      grid-template-columns: 1fr;
      gap: 24px;
    }
    .gs-footer-bottom {
      flex-direction: column;
      gap: 12px;
      text-align: center;
    }
  }

  .gs-mobile-menu {
    position: fixed;
    top: 0;
    left: -100%;
    width: 280px;
    height: 100vh;
    background: var(--gs-card-bg);
    border-right: 1px solid var(--gs-card-border);
    z-index: 200;
    padding: 24px;
    transition: left 0.3s ease;
    box-shadow: var(--gs-shadow-lg);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .gs-mobile-menu.open {
    left: 0;
  }
  .gs-mobile-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 150;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
  }
  .gs-mobile-overlay.open {
    opacity: 1;
    visibility: visible;
  }
  .gs-mobile-nav {
    list-style: none;
    margin-top: 24px;
  }
  .gs-mobile-nav li {
    margin-bottom: 12px;
  }
  .gs-mobile-nav a {
    display: block;
    padding: 8px 12px;
    border-radius: 8px;
    font-weight: 600;
    color: var(--gs-text);
  }
  .gs-mobile-nav a:hover {
    background: var(--gs-primary-light);
    color: var(--gs-primary);
  }

  .gs-post-toc {
    background: var(--gs-bg);
    border: 1px solid var(--gs-card-border);
    border-radius: 12px;
    padding: 18px;
    margin: 24px 0;
  }
  .gs-post-toc-title {
    font-weight: 700;
    font-size: 15px;
    display: flex;
    justify-content: space-between;
    cursor: pointer;
  }



<!--CSS Bagian Tengah: Judul, Kategori, dan Deskripsi -->

.gosmart-tool-card {
            background-color: #ffffff;
            border: 1px solid #f1f5f9;
            border-radius: 20px;
            padding: 20px;
            width: 100%;
            max-width: 440px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.02), 0 2px 4px -2px rgba(0, 0, 0, 0.02);
            display: flex;
            flex-direction: column;
            gap: 16px;
            font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            box-sizing: border-box;
        }
        .gosmart-tool-card *, .gosmart-tool-card *::before, .gosmart-tool-card *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }
        .gosmart-card-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
        }
        .gosmart-tool-icon {
            width: 48px;
            height: 48px;
            background-color: #eff6ff;
            color: #2563eb;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            font-weight: bold;
        }
        .gosmart-card-action-right {
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .gosmart-badge-populer {
            background-color: #fefce8;
            color: #854d0e;
            font-size: 12px;
            font-weight: 500;
            padding: 4px 10px;
            border-radius: 20px;
            border: 1px solid #fef08a;
        }
        .gosmart-btn-favorite {
            width: 36px;
            height: 36px;
            background: transparent;
            border: 1px solid #e2e8f0;
            border-radius: 12px;
            color: #64748b;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
        }
        .gosmart-card-body {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }
        .gosmart-tool-title {
            font-size: 18px;
            font-weight: 700;
            color: #0f172a;
        }
        .gosmart-tool-category {
            font-size: 13px;
            font-weight: 500;
            color: #64748b;
            margin-bottom: 4px;
        }
        .gosmart-tool-description {
            font-size: 14px;
            color: #475569;
            line-height: 1.5;
        }
        .gosmart-card-footer {
            border-top: 1px solid #f8fafc;
            padding-top: 14px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 13px;
        }
        .gosmart-tool-side-info {
            display: flex;
            align-items: center;
            gap: 6px;
            color: #64748b;
            font-weight: 500;
        }
        .gosmart-btn-open-tool {
            color: #2563eb;
            text-decoration: none;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 4px;
        }
        .gosmart-btn-open-tool:hover {
            opacity: 0.8;
        }




/* --- CSS Khusus Dokumentasi (Scoped) --- */
.docs-container {
    --primary-color: #2563eb;
    --bg-color: #ffffff;
    --sidebar-bg: #f8fafc;
    --text-color: #1e293b;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --code-bg: #0f172a;
    --code-text: #e2e8f0;

    font-family: 'Inter', sans-serif;
    color: var(--text-color);
    background-color: var(--bg-color);
    display: flex;
    flex-direction: column;
    width: 100%;
}

.docs-container *, .docs-container *::before, .docs-container *::after {
    box-sizing: border-box;
}

/* Sub-Header Dokumentasi */
.docs-container .docs-header {
    height: 60px;
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 2rem;
    position: sticky;
    top: 0;
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(8px);
    z-index: 50;
}

.docs-container .logo {
    font-weight: 700;
    font-size: 1.25rem;
    color: var(--primary-color);
    text-decoration: none;
}

.docs-container .search-bar input {
    padding: 0.5rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    width: 250px;
    font-size: 0.9rem;
    outline: none;
}

.docs-container .search-bar input:focus {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

/* Layout Utama */
.docs-container .docs-layout {
    display: flex;
    flex: 1;
    max-width: 1400px;
    width: 100%;
    margin: 0 auto;
}

/* Sidebar Navigasi Kiri */
.docs-container aside.docs-sidebar {
    width: 280px;
    background-color: var(--sidebar-bg);
    border-right: 1px solid var(--border-color);
    padding: 2rem 1.5rem;
    position: sticky;
    top: 60px;
    height: calc(100vh - 60px);
    overflow-y: auto;
    flex-shrink: 0;
}

.docs-container .menu-category {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    font-weight: 700;
    margin-bottom: 0.75rem;
    margin-top: 1.5rem;
}

.docs-container .menu-category:first-child {
    margin-top: 0;
}

.docs-container .menu-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding: 0;
    margin: 0;
}

.docs-container .menu-list a {
    text-decoration: none;
    color: var(--text-muted);
    font-size: 0.9rem;
    padding: 0.35rem 0.5rem;
    border-radius: 4px;
    display: block;
    transition: all 0.2s;
}

.docs-container .menu-list a:hover, 
.docs-container .menu-list a.active {
    color: var(--primary-color);
    background-color: rgba(37, 99, 235, 0.05);
    font-weight: 500;
}

/* Konten Utama */
.docs-container main.docs-content {
    flex: 1;
    padding: 3rem 4rem;
    max-width: 850px;
}

.docs-container h1 {
    font-size: 2.25rem;
    font-weight: 700;
    margin-bottom: 1rem;
    letter-spacing: -0.025em;
}

.docs-container h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-top: 2.5rem;
    margin-bottom: 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--border-color);
}

.docs-container p {
    line-height: 1.7;
    margin-bottom: 1.25rem;
    color: #334155;
}

.docs-container pre {
    background-color: var(--code-bg);
    color: var(--code-text);
    padding: 1.25rem;
    border-radius: 8px;
    font-family: 'Fira Code', monospace;
    font-size: 0.9rem;
    overflow-x: auto;
    margin-bottom: 1.5rem;
}

.docs-container code {
    font-family: 'Fira Code', monospace;
}

.docs-container p code, 
.docs-container li code {
    background-color: #f1f5f9;
    color: #0f172a;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    font-size: 0.85em;
    border: 1px solid var(--border-color);
}

.docs-container .callout {
    background-color: #eff6ff;
    border-left: 4px solid var(--primary-color);
    padding: 1rem 1.25rem;
    border-radius: 0 6px 6px 0;
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.docs-container .callout strong {
    color: #1e40af;
}

/* Responsif */
@media (max-width: 768px) {
    .docs-container .docs-layout {
        flex-direction: column;
    }
    .docs-container aside.docs-sidebar {
        width: 100%;
        height: auto;
        position: relative;
        top: 0;
    }
    .docs-container main.docs-content {
        padding: 1.5rem;
    }
    .docs-container .docs-header {
        padding: 0 1rem;
    }
    .docs-container .search-bar {
        display: none;
    }
}

body.script:
//
function initTheme() {
  const saved = localStorage.getItem('gs-theme');
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  if (saved === 'dark' || (!saved && prefersDark)) {
    document.documentElement.setAttribute('data-theme', 'dark');
    updateIcons('dark');
  } else {
    document.documentElement.setAttribute('data-theme', 'light');
    updateIcons('light');
  }
}

function toggleTheme() {
  const current = document.documentElement.getAttribute('data-theme');
  const target = current === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', target);
  localStorage.setItem('gs-theme', target);
  updateIcons(target);
}

function updateIcons(mode) {
  const sun = document.getElementById('theme-icon-sun');
  const moon = document.getElementById('theme-icon-moon');
  if (sun && moon) {
    if (mode === 'dark') {
      sun.style.display = 'block';
      moon.style.display = 'none';
    } else {
      sun.style.display = 'none';
      moon.style.display = 'block';
    }
  }
}

function toggleMobileNav() {
  const menu = document.getElementById('gs-mobile-menu');
  const overlay = document.getElementById('gs-mobile-overlay');
  if (menu && overlay) {
    menu.classList.toggle('open');
    overlay.classList.toggle('open');
  }
}

document.addEventListener('DOMContentLoaded', function() {
  initTheme();
  const yearEl = document.getElementById('current-year');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  const article = document.getElementById('article-content-body');
  const tocBox = document.getElementById('post-toc-container');
  const tocList = document.getElementById('post-toc-list');

  if (article && tocBox && tocList) {
    const headings = article.querySelectorAll('h2, h3');
    if (headings.length === 0) {
      tocBox.style.display = 'none';
      return;
    }
    headings.forEach(function(h, i) {
      if (!h.id) {
        h.id = 'heading-sec-' + i;
      }
      const li = document.createElement('li');
      li.style.marginBottom = '6px';
      li.style.fontSize = '14px';
      if (h.tagName.toLowerCase() === 'h3') {
        li.style.marginLeft = '18px';
        li.style.listStyleType = 'circle';
      }
      const a = document.createElement('a');
      a.href = '#' + h.id;
      a.textContent = h.textContent;
      li.appendChild(a);
      tocList.appendChild(li);
    });
  }
});

function togglePostToc() {
  const list = document.getElementById('post-toc-list');
  const label = document.getElementById('post-toc-toggle-label');
  if (list && label) {
    if (list.style.display === 'none') {
      list.style.display = 'block';
      label.textContent = '[Sembunyikan]';
    } else {
      list.style.display = 'none';
      label.textContent = '[Tampilkan]';
    }
  }
}
//
